```python
# 推斷：資料表=上期報價 & 本期報價（表頭第 1 列）｜欄位=品號、品名、單價、幣別、計價單位｜主檔=品號｜鍵=品號｜篩選=比較兩期差異｜輸出=增刪對照表

from openpyxl import load_workbook

# 讀取工作簿
wb = load_workbook(INPUT_PATH)

# 讀取上期報價資料
ws_prev = wb['上期報價']
prev_data = {}
for row in range(2, ws_prev.max_row + 1):
    item_no = ws_prev.cell(row=row, column=1).value
    if item_no:
        prev_data[item_no] = [
            ws_prev.cell(row=row, column=2).value,  # 品名
            ws_prev.cell(row=row, column=3).value,  # 單價
            ws_prev.cell(row=row, column=4).value,  # 幣別
            ws_prev.cell(row=row, column=5).value   # 計價單位
        ]

# 讀取本期報價資料
ws_curr = wb['本期報價']
curr_data = {}
for row in range(2, ws_curr.max_row + 1):
    item_no = ws_curr.cell(row=row, column=1).value
    if item_no:
        curr_data[item_no] = [
            ws_curr.cell(row=row, column=2).value,  # 品名
            ws_curr.cell(row=row, column=3).value,  # 單價
            ws_curr.cell(row=row, column=4).value,  # 幣別
            ws_curr.cell(row=row, column=5).value   # 計價單位
        ]

# 建立增刪對照表工作表
ws_diff = wb.create_sheet('增刪對照表')

# 寫入表頭（差異類型 + 原欄位）
headers = ['差異類型', '品號', '品名', '單價', '幣別', '計價單位']
for col, header in enumerate(headers, 1):
    ws_diff.cell(row=1, column=col).value = header

# 設定表頭粗體
from openpyxl.styles import Font
for col in range(1, len(headers) + 1):
    ws_diff.cell(row=1, column=col).font = Font(bold=True)

# 收集差異記錄
diff_records = []

# 檢查刪除的品號（上期有，本期沒有）
for item_no in prev_data:
    if item_no not in curr_data:
        diff_records.append(['刪除', item_no] + prev_data[item_no])

# 檢查新增的品號（本期有，上期沒有）
for item_no in curr_data:
    if item_no not in prev_data:
        diff_records.append(['新增', item_no] + curr_data[item_no])

# 檢查修改的品號（兩期都有但內容不同）
for item_no in prev_data:
    if item_no in curr_data:
        if prev_data[item_no] != curr_data[item_no]:
            diff_records.append(['修改', item_no] + curr_data[item_no])

# 寫入差異記錄
for row_idx, record in enumerate(diff_records, 2):
    for col_idx, value in enumerate(record, 1):
        ws_diff.cell(row=row_idx, column=col_idx).value = value

# 儲存工作簿
wb.save(OUTPUT_PATH)
```

```python
# 推斷：資料表=上期報價、本期報價（表頭第 1 列）｜欄位=品號、品名、單價、幣別、計價單位｜主檔=上期報價｜鍵=品號｜篩選=比對兩表差異｜輸出=增刪對照表

from openpyxl import load_workbook

# 讀取工作簿
wb = load_workbook(INPUT_PATH)

# 取得兩個工作表
ws_prev = wb['上期報價']
ws_curr = wb['本期報價']

# 建立欄名→索引對照（表頭在第 1 列）
prev_headers = {cell.value: idx for idx, cell in enumerate(ws_prev[1], start=1)}
curr_headers = {cell.value: idx for idx, cell in enumerate(ws_curr[1], start=1)}

# 讀取上期資料（以品號為鍵）
prev_data = {}
for row in range(2, ws_prev.max_row + 1):
    key = ws_prev.cell(row, prev_headers['品號']).value
    if key:
        prev_data[key] = [ws_prev.cell(row, col).value for col in range(1, 6)]

# 讀取本期資料（以品號為鍵）
curr_data = {}
for row in range(2, ws_curr.max_row + 1):
    key = ws_curr.cell(row, curr_headers['品號']).value
    if key:
        curr_data[key] = [ws_curr.cell(row, col).value for col in range(1, 6)]

# 建立新工作表「增刪對照表」
ws_new = wb.create_sheet('增刪對照表')

# 寫入表頭（差異類型 + 原欄位）
new_headers = ['差異類型', '品號', '品名', '單價', '幣別', '計價單位']
for col, header in enumerate(new_headers, start=1):
    ws_new.cell(1, col, header)

# 設定表頭粗體
from openpyxl.styles import Font
bold_font = Font(bold=True)
for col in range(1, 7):
    ws_new.cell(1, col).font = bold_font

# 收集差異資料
diff_rows = []

# 刪除的項目（上期有、本期無）
for key in prev_data:
    if key not in curr_data:
        diff_rows.append(['刪除'] + prev_data[key])

# 新增的項目（本期有、上期無）
for key in curr_data:
    if key not in prev_data:
        diff_rows.append(['新增'] + curr_data[key])

# 寫入資料
for row_idx, row_data in enumerate(diff_rows, start=2):
    for col_idx, value in enumerate(row_data, start=1):
        ws_new.cell(row_idx, col_idx, value)

# 儲存工作簿
wb.save(OUTPUT_PATH)
```

```python
# 推斷：資料表=舊版 BOM/新版 BOM（表頭第 1 列）｜欄位=料號/品名/數量/類別/單位｜主檔=料號｜鍵=A 欄料號｜篩選=新舊版差異｜輸出=新工作表「BOM 差異比較」

from openpyxl import Workbook, load_workbook

# 讀取工作簿
wb = load_workbook(INPUT_PATH)

# 讀取舊版 BOM 資料（料號為鍵）
old_ws = wb['舊版 BOM']
old_data = {}
for row in range(2, old_ws.max_row + 1):
    part_no = old_ws.cell(row=row, column=1).value
    if part_no:
        old_data[part_no] = [old_ws.cell(row=row, column=c).value for c in range(1, 6)]

# 讀取新版 BOM 資料（料號為鍵）
new_ws = wb['新版 BOM']
new_data = {}
for row in range(2, new_ws.max_row + 1):
    part_no = new_ws.cell(row=row, column=1).value
    if part_no:
        new_data[part_no] = [new_ws.cell(row=row, column=c).value for c in range(1, 6)]

# 找出新增（新版有舊版無）和刪除（舊版有新版無）
added = []
for part_no in new_data:
    if part_no not in old_data:
        added.append(['新增'] + new_data[part_no])

deleted = []
for part_no in old_data:
    if part_no not in new_data:
        deleted.append(['刪除'] + old_data[part_no])

# 建立新工作表
diff_ws = wb.create_sheet('BOM 差異比較')

# 寫入表頭（差異類型 + 原欄位）
headers = ['差異類型', '料號', '品名', '數量', '類別', '單位']
for col, h in enumerate(headers, 1):
    diff_ws.cell(row=1, column=col, value=h)

# 寫入資料：新增排前面，刪除排後面
row_num = 2
for item in added:
    for col, val in enumerate(item, 1):
        diff_ws.cell(row=row_num, column=col, value=val)
    row_num += 1

for item in deleted:
    for col, val in enumerate(item, 1):
        diff_ws.cell(row=row_num, column=col, value=val)
    row_num += 1

# 儲存工作簿
wb.save(OUTPUT_PATH)
```

```python
# 推斷：資料表=舊版 BOM, 新版 BOM（表頭第 1 列）｜欄位=料號、品名、數量、類別、單位｜鍵=料號（A 欄）｜輸出=新工作表「變更記錄」

from openpyxl import load_workbook

# 讀取工作簿
wb = load_workbook(INPUT_PATH)

# 讀取舊版和新版 BOM
old_ws = wb['舊版 BOM']
new_ws = wb['新版 BOM']

# 取得表頭（第 1 列）
old_headers = [old_ws.cell(1, col).value for col in range(1, old_ws.max_column + 1)]
new_headers = [new_ws.cell(1, col).value for col in range(1, new_ws.max_column + 1)]

# 建立欄名→索引對照
old_col_map = {h: i for i, h in enumerate(old_headers, start=1)}
new_col_map = {h: i for i, h in enumerate(new_headers, start=1)}

# 讀取資料（從第 2 列開始），以料號為鍵
old_data = {}
old_row_order = []  # 記錄舊版列序
for row in range(2, old_ws.max_row + 1):
    key = old_ws.cell(row, old_col_map['料號']).value
    old_row_order.append(key)
    old_data[key] = {h: old_ws.cell(row, old_col_map[h]).value for h in old_headers if h != '料號'}

new_data = {}
for row in range(2, new_ws.max_row + 1):
    key = new_ws.cell(row, new_col_map['料號']).value
    new_data[key] = {h: new_ws.cell(row, new_col_map[h]).value for h in new_headers if h != '料號'}

# 比對變更，按照舊版列序、同列依原表欄位順序
changes = []
for key in old_row_order:
    if key in new_data:
        # 按照原表欄位順序（品名、數量、類別、單位）
        for header in old_headers:
            if header == '料號':
                continue
            old_val = old_data[key].get(header)
            new_val = new_data[key].get(header)
            if old_val != new_val:
                changes.append([key, header, old_val, new_val])

# 創建新工作表（放在最後）
if '變更記錄' in wb.sheetnames:
    del wb['變更記錄']
change_ws = wb.create_sheet('變更記錄')

# 寫入表頭
change_ws.append(['料號', '變更欄位', '舊值', '新值'])

# 寫入資料
for change in changes:
    change_ws.append(change)

# 儲存
wb.save(OUTPUT_PATH)
```
